-- ============================================================================
-- REPLICA SCHEMA: Raport Madrasah Diniah
-- PostgreSQL 14+ Relational Database Schema
-- Generated by replica-architect
-- ============================================================================

-- Ekstensi UUID untuk ID acak
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 1. PROFIL MADRASAH
CREATE TABLE IF NOT EXISTS madrasah_profile (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    nama_madrasah VARCHAR(150) NOT NULL DEFAULT 'Madrasah Diniah Darul Barokah',
    nsm VARCHAR(30) DEFAULT '',
    npsn VARCHAR(30) DEFAULT '',
    alamat TEXT NOT NULL DEFAULT 'Jatipurwo IV/14A Surabaya',
    kelurahan VARCHAR(100) DEFAULT '',
    kecamatan VARCHAR(100) DEFAULT 'Semampir',
    kota VARCHAR(100) DEFAULT 'Surabaya',
    provinsi VARCHAR(100) DEFAULT 'Jawa Timur',
    logo_url TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 2. AKUN & PENGGUNA (Guru, Wali Kelas, Administrator)
CREATE TABLE IF NOT EXISTS users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    username VARCHAR(50) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    nama_lengkap VARCHAR(150) NOT NULL,
    nip VARCHAR(50) DEFAULT '',
    telepon VARCHAR(25) DEFAULT '',
    role VARCHAR(20) NOT NULL DEFAULT 'guru' CHECK (role IN ('admin', 'guru')),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_users_username ON users(username);
CREATE INDEX IF NOT EXISTS idx_users_role ON users(role);

-- 3. PERIODE TAHUN AJARAN & SEMESTER
CREATE TABLE IF NOT EXISTS tahun_ajaran (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tahun VARCHAR(20) NOT NULL,            -- e.g. '2024/2025'
    semester VARCHAR(10) NOT NULL CHECK (semester IN ('Ganjil', 'Genap')),
    is_active BOOLEAN NOT NULL DEFAULT FALSE,
    tanggal_cetak DATE,
    tempat_cetak VARCHAR(100) DEFAULT 'Surabaya',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_tahun_semester UNIQUE (tahun, semester)
);

-- 4. KEPALA MADRASAH (Pejabat Penandatangan)
CREATE TABLE IF NOT EXISTS kepala_madrasah (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    nama VARCHAR(150) NOT NULL,
    nip VARCHAR(50) DEFAULT '',
    jabatan VARCHAR(100) NOT NULL DEFAULT 'Kepala Madrasah',
    ttd_digital_url TEXT,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 5. ROMBONGAN BELAJAR (ROMBEL)
CREATE TABLE IF NOT EXISTS rombel (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    jenjang VARCHAR(10) NOT NULL CHECK (jenjang IN ('MI', 'MTs', 'MA')),
    tingkat INT NOT NULL CHECK (tingkat BETWEEN 1 AND 12),
    nama_rombel VARCHAR(10) NOT NULL DEFAULT 'A', -- 'A', 'B', 'C', dll
    wali_kelas_id UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_rombel UNIQUE (jenjang, tingkat, nama_rombel)
);
CREATE INDEX IF NOT EXISTS idx_rombel_jenjang_tingkat ON rombel(jenjang, tingkat);
CREATE INDEX IF NOT EXISTS idx_rombel_wali ON rombel(wali_kelas_id);

-- 6. DATA SANTRI / SISWA
CREATE TABLE IF NOT EXISTS siswa (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    nis VARCHAR(50) UNIQUE NOT NULL,
    nisn VARCHAR(50) DEFAULT '',
    nama VARCHAR(150) NOT NULL,
    jenis_kelamin VARCHAR(2) NOT NULL CHECK (jenis_kelamin IN ('L', 'P')),
    tempat_lahir VARCHAR(100) DEFAULT '',
    tanggal_lahir DATE,
    nama_wali VARCHAR(150) DEFAULT '',
    alamat TEXT DEFAULT '',
    rombel_id UUID REFERENCES rombel(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_siswa_rombel ON siswa(rombel_id);
CREATE INDEX IF NOT EXISTS idx_siswa_nama ON siswa(nama);
CREATE INDEX IF NOT EXISTS idx_siswa_nis ON siswa(nis);

-- 7. MATA PELAJARAN & KKM
CREATE TABLE IF NOT EXISTS mapel (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    jenjang VARCHAR(10) NOT NULL CHECK (jenjang IN ('MI', 'MTs', 'MA')),
    nama VARCHAR(100) NOT NULL,
    urutan INT NOT NULL DEFAULT 1,
    kkm NUMERIC(5,2) NOT NULL DEFAULT 70.00 CHECK (kkm >= 0 AND kkm <= 100),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_mapel_jenjang_nama UNIQUE (jenjang, nama)
);
CREATE INDEX IF NOT EXISTS idx_mapel_jenjang ON mapel(jenjang, urutan);

-- 8. NILAI SANTRI (Inti Penilaian Akademik)
CREATE TABLE IF NOT EXISTS nilai (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    siswa_id UUID NOT NULL REFERENCES siswa(id) ON DELETE CASCADE,
    mapel_id UUID NOT NULL REFERENCES mapel(id) ON DELETE CASCADE,
    tahun_ajaran_id UUID NOT NULL REFERENCES tahun_ajaran(id) ON DELETE CASCADE,
    nilai_angka NUMERIC(5,2) NOT NULL CHECK (nilai_angka >= 0 AND nilai_angka <= 100),
    predikat VARCHAR(5) NOT NULL DEFAULT 'B' CHECK (predikat IN ('A', 'B', 'C', 'D')),
    is_tuntas BOOLEAN NOT NULL DEFAULT TRUE,
    catatan_wali TEXT DEFAULT '',
    updated_by UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    -- Constraint Unik Kunci: 1 Siswa hanya boleh memiliki 1 record nilai per mapel di periode yang sama
    CONSTRAINT uq_nilai_siswa_mapel_periode UNIQUE (siswa_id, mapel_id, tahun_ajaran_id)
);
CREATE INDEX IF NOT EXISTS idx_nilai_siswa ON nilai(siswa_id, tahun_ajaran_id);
CREATE INDEX IF NOT EXISTS idx_nilai_mapel ON nilai(mapel_id, tahun_ajaran_id);

